use std::fs
use std::json

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let parsed = json.parse_string::<Vec<Order>>(text)
    match parsed {
        Ok(orders) => {
            let mut names: Vec<string> = []
            let mut totals: Vec<float> = []
            for o in orders {
                let mut t = 0.0
                for it in o.items {
                    t += (it.qty as float) * it.price
                }
                let mut found = false
                let mut i = 0
                while i < names.len() as int {
                    if names[i] == o.customer {
                        totals[i] = totals[i] + t
                        found = true
                    }
                    i += 1
                }
                if !found {
                    names.push(o.customer)
                    totals.push(t)
                }
            }
            let mut idx: Vec<int> = []
            let mut k = 0
            while k < names.len() as int {
                idx.push(k)
                k += 1
            }
            idx.sort_by(|a, b| names[*a].cmp(&names[*b]))
            for j in idx {
                println("${names[j]} ${totals[j]:.2}")
            }
        }
        Err(_) => {
            println("invalid input")
            std::process::exit(1)
        }
    }
}

